export const tnbcTerms: TermInput[] = [
  tm({ id: "er-pr-negative-threshold", name: "ER and PR negative under 1 percent (the triple-negative threshold, and ER-low)", category: "Pathology", wikipedia: W("Estrogen_receptor_test"),
    aka: ["ER-negative under 1 percent", "ER Low Positive", "ER-low breast cancer", "ER 1 to 10 percent", "Hormone receptor-negative threshold", "PR-negative"],
    tldr: "A breast cancer counts as oestrogen receptor negative when fewer than 1 in 100 of its cells stain for the receptor, and the same rule applies to progesterone receptor. Tumours with 1 to 10 percent staining are labelled ER low positive, but they behave like triple-negative cancers and in some countries are treated as such.",
    summary: "The ASCO/CAP guideline recommends ER testing of invasive breast cancers by validated immunohistochemistry as the standard for predicting endocrine therapy benefit: samples with 1 to 100 percent of tumour nuclei positive are ER positive; fewer than 1 percent or 0 percent is ER negative; and because data on endocrine benefit for 1 to 10 percent staining are limited, those samples are reported in a new category, ER Low Positive, with a recommended comment, laboratory standard operating procedures for low or absent staining, and the status of controls reported for 0 to 10 percent cases; the same principles apply to PR, which is used mainly for prognosis in ER-positive disease (Allison 2020). NICE NG101 asks for ER, PR and HER2 to be assessed together at diagnosis, ER by standardised quality-assured immunohistochemistry reported quantitatively, and defines triple-negative as each scored negative under local multidisciplinary team guidelines (NG101 1.3 and the terms section). The ER-low band behaves like triple-negative disease: in a US registry of 516 stage I to III HER2-negative patients with ER and PR of 10 percent or less, the 12.6 percent with 1 to 10 percent staining matched the rest for germline BRCA prevalence, chemotherapy use, pathological complete response (51.3 against 49.2 percent) and three-year recurrence-free (82.4 against 82.5 percent) and overall survival (Yoder 2022); in 406 Italian patients ER 1 to 9 percent tumours had the same five-year relapse-free (73.1 against 74.0 percent) and overall survival (76.7 against 82.3 percent) and pathological complete response (44 against 38 percent) as ER-negative tumours (Dieci 2021); and Sweden kept a 10 percent threshold when international guidelines dropped to 1 percent in 2010, treating ER 1 to 9 percent HER2-negative tumours as triple-negative, with 9.9 percent of 5,655 tumours in 2008 to 2020 in that band and no survival difference from ER-zero disease (Acs 2024). The practical consequence is that ER-low patients are often excluded from triple-negative trials of immunotherapy and ADCs, so evidence for those drugs in the band is thin (Yoder 2022).",
    cancers: ["tnbc", "breast-hr-positive", "tnbc-early"], terms: ["her2-low", "pcr"], links: [SRC.allison2020, SRC.ng101, SRC.yoder2022, SRC.dieci2021, SRC.acs2024] }),

  tm({ id: "her2-low-and-trop2-adc-eligibility-tnbc", name: "HER2-low eligibility for trastuzumab deruxtecan, and TROP2 ADCs without a test (triple-negative disease)", category: "Biomarkers", wikipedia: W("Trastuzumab_deruxtecan"),
    aka: ["HER2-low TNBC", "HER2 0 versus 1+", "T-DXd eligibility in triple-negative breast cancer", "Sacituzumab govitecan eligibility", "TROP2 testing not required"],
    tldr: "Two antibody-drug conjugates reach triple-negative breast cancer by different rules. Trastuzumab deruxtecan needs the tumour to show a little HER2 (a score of 1+, or 2+ without gene amplification), so the pathologist's call between 0 and 1+ matters. Sacituzumab govitecan targets TROP2, which almost all breast cancers carry, and is given without any test.",
    summary: "HER2 scoring follows the ASCO/CAP algorithm: immunohistochemistry 0, 1+, 2+ (weak to moderate complete membrane staining in more than 10 percent of cells, reflexed to in situ hybridisation) or 3+, with the 2018 focused update handling the uncommon dual-probe ISH groups (Wolff 2018). HER2-low means 1+ or 2+ without amplification. DESTINY-Breast04 randomised 557 patients with HER2-low metastatic breast cancer after one or two lines of chemotherapy to trastuzumab deruxtecan or physician's choice chemotherapy; 494 (88.7 percent) had hormone receptor-positive and 63 (11.3 percent) hormone receptor-negative disease; among all patients median progression-free survival was 9.9 against 5.1 months (hazard ratio 0.50) and overall survival 23.4 against 16.8 months (0.64), with drug-related interstitial lung disease or pneumonitis in 12.1 percent and grade 5 events in 0.8 percent (Modi 2022). The 2023 ASCO-CAP update affirmed the 2018 testing recommendations, declined to create new HER2-low or HER2-ultralow result categories because IHC 0 tumours were excluded from the trial and no biological threshold at 0 versus 1+ is established, but added a reporting comment and best-practice steps to distinguish 0 from 1+ now that the distinction decides eligibility (Wolff 2023). The parent record's estimate that about a third of triple-negative tumours are HER2-low is the earlier unsourced text; the biomarker readouts carry the label thresholds. Sacituzumab govitecan is an antibody to TROP2, expressed in the majority of breast cancers, coupled to SN-38; in ASCENT (468 patients without brain metastases, all previously treated with taxanes) it gave median progression-free survival of 5.6 against 1.7 months and overall survival of 12.1 against 6.7 months versus single-agent chemotherapy, with no TROP2 test required for entry (Bardia 2021); NICE recommends it after two or more systemic therapies (TA819, August 2022), and the first-line rows on the parent page record the later ASCENT-03 and ASCENT-04 approvals. The open question on the parent page, whether a second TOP1-payload ADC works after the first, applies to both drugs.",
    cancers: ["tnbc", "tnbc-metastatic", "her2-low-metastatic-breast-cancer"], terms: ["her2-low", "er-pr-negative-threshold"], drugs: ["trastuzumab-deruxtecan", "sacituzumab-govitecan"], targets: ["her2", "trop2"], trials: ["destiny-breast04", "ascent"], technologies: ["adc"],
    links: [SRC.wolff2018, SRC.wolff2023, SRC.modi2022, SRC.bardia2021, SRC.ta819] }),

  tm({ id: "pd-l1-cps-10-tnbc", name: "PD-L1 combined positive score 10 in triple-negative breast cancer", category: "Biomarkers", wikipedia: W("PD-L1"),
    aka: ["CPS 10 in TNBC", "PD-L1 CPS of 10 or more", "PD-L1-positive triple-negative breast cancer", "22C3 CPS 10", "SP142 IC 1 percent (IMpassion130)"],
    tldr: "In metastatic triple-negative breast cancer the immunotherapy pembrolizumab is only given when a PD-L1 stain of the tumour scores 10 or more on the combined positive score, because that is the group in which the trial showed people lived longer. For early disease before surgery no PD-L1 test is needed: pembrolizumab helped regardless.",
    summary: "The combined positive score is the number of PD-L1-staining tumour cells, lymphocytes and macrophages divided by the total number of viable tumour cells, multiplied by 100 (Cortes 2022). KEYNOTE-355 randomised 847 patients with untreated locally recurrent inoperable or metastatic triple-negative breast cancer 2:1 to pembrolizumab or placebo with the investigator's chemotherapy (nab-paclitaxel, paclitaxel or gemcitabine-carboplatin), with PD-L1 tested centrally by the 22C3 assay. Progression-free survival at the interim analysis was 9.7 against 5.6 months in the CPS 10 or more group (hazard ratio 0.65, primary objective met), 7.6 against 5.6 months in CPS 1 or more (0.74, not significant) and 7.5 against 5.6 months overall (0.82, not tested), the effect increasing with PD-L1 enrichment (Cortes 2020). At the final analysis (median follow-up 44.1 months) overall survival in the CPS 10 group was 23.0 against 16.1 months (hazard ratio 0.73, significant), 17.6 against 16.0 months in CPS 1 or more (0.86, not significant) and 17.2 against 15.5 months in all patients (0.89, not tested); grade 3 to 5 treatment-related events occurred in 68.1 against 66.9 percent (Cortes 2022). NICE recommends pembrolizumab with paclitaxel or nab-paclitaxel for untreated triple-negative locally recurrent unresectable or metastatic breast cancer in the population the appraisal covers (TA801, June 2022). A different assay and score defined the earlier atezolizumab result: IMpassion130 used the SP142 immune-cell score with positivity at 1 percent or more of the tumour area; median progression-free survival was 7.5 against 5.0 months and overall survival 25.0 against 15.5 months in the PD-L1-positive subgroup, without a significant overall survival gain in the whole population (Schmid 2018), and the parent page's history records that approval was later withdrawn. Early disease needs no PD-L1 test: in KEYNOTE-522 pembrolizumab with chemotherapy raised pathological complete response from 51.2 to 64.8 percent in stage II and III disease unselected for PD-L1 (Schmid 2020) and five-year overall survival from 81.7 to 86.6 percent (Schmid 2024); NICE TA851 (December 2022) recommends it for triple-negative early or locally advanced breast cancer at high risk of recurrence. The biomarker readout pd-l1-cps carries the label wording for every CPS threshold across cancers.",
    cancers: ["tnbc", "tnbc-metastatic", "tnbc-early"], terms: ["cps", "tils"], drugs: ["pembrolizumab", "atezolizumab"], targets: ["pdl1", "pd1"], trials: ["keynote-355", "impassion130", "keynote-522"], technologies: ["checkpoint-inhibitor"],
    links: [SRC.cortes2020, SRC.cortes2022, SRC.schmid2018, SRC.schmid2020, SRC.schmid2024, SRC.ta801, SRC.ta851] }),

  tm({ id: "hrd-in-breast-cancer", name: "Homologous recombination deficiency (HRD) in breast cancer", category: "Biomarkers", wikipedia: W("Homologous_recombination"),
    aka: ["HRD score in breast cancer", "HRD in TNBC", "Genomic instability score 42", "HR-deficient triple-negative breast cancer", "BRCAness"],
    tldr: "Homologous recombination deficiency means a tumour cannot mend double-strand DNA breaks properly, most often because BRCA1 or BRCA2 is lost. About seven in ten triple-negative tumours score as deficient, and they respond better to platinum chemotherapy; but unlike ovarian cancer, no breast cancer drug is approved on the basis of an HRD score, only on a germline BRCA result.",
    summary: "Three DNA-based measures of genomic instability (loss of heterozygosity, telomeric allelic imbalance and large-scale state transitions) are summed into an HRD score, with deficiency defined as a score of 42 or more or a BRCA1/2 mutation. In three neoadjuvant platinum trials in triple-negative disease, HR deficiency predicted residual cancer burden 0 or I and pathological complete response (odds ratios 4.96 and 6.52 in the platinum, gemcitabine and iniparib trial; 10.18 and 17.00 in two cisplatin trials), remained significant after adjustment for clinical variables, and identified responders among BRCA1/2 non-mutated tumours (Telli 2016). In GeparSixto, HRD was measured in 193 of 315 triple-negative participants: 136 (70.5 percent) were HR deficient, 82 of them (60.3 percent) with a high score but no tumour BRCA mutation; HR deficiency independently predicted pathological complete response (odds ratio 2.60), and adding carboplatin raised the rate from 33.9 to 63.5 percent in HR-deficient tumours but only from 20.0 to 29.6 percent in non-deficient tumours, with the interaction test not significant, so HRD predicted response but not carboplatin benefit; carboplatin improved disease-free survival in triple-negative disease overall (hazard ratio 0.56) (Loibl 2018). Beyond germline BRCA, olaparib produced confirmed responses in metastatic breast cancer with germline PALB2 mutations (objective response 82 percent, median progression-free survival 13.3 months) and somatic BRCA1/2 mutations (50 percent, 6.3 months) but none with ATM or CHEK2 mutations alone (TBCRC 048, Tung 2020). Regulatory use differs from ovarian cancer: NICE's adjuvant olaparib recommendation rests on a germline BRCA mutation (TA886), not an HRD score, and the platinum recommendation in NG101 1.8 applies to all triple-negative disease needing neoadjuvant chemotherapy, HRD-tested or not. The site's general HRD term and the hrd-positive readout carry the ovarian thresholds and assays.",
    cancers: ["tnbc", "brca-associated-tnbc", "tnbc-early"], terms: ["hrd", "germline-vs-somatic", "pcr", "rcb"], targets: ["brca", "parp"], drugs: ["carboplatin", "olaparib"], technologies: ["hrd-testing", "platinum", "parp-inhibitor"], trials: ["geparsixto"],
    links: [SRC.telli2016, SRC.loibl2018, SRC.tung2020, SRC.ta886, SRC.ng101] }),

  tm({ id: "germline-brca-testing-criteria-tnbc", name: "Germline BRCA testing criteria for triple-negative breast cancer (UK)", category: "Genomics & genetics", wikipedia: W("BRCA_mutation"),
    aka: ["Who gets BRCA testing", "Mainstream genetic testing criteria", "NICE genetic testing threshold 10 percent", "TNBC under 50 BRCA testing", "TNBC under 60 testing", "Manchester score", "R208 testing criteria"],
    tldr: "In the NHS a blood test for inherited BRCA1 and BRCA2 faults is offered to every woman under 50 with triple-negative breast cancer, whatever her family history, and hospital testing criteria now extend that to triple-negative disease under 60 and any breast cancer under 40. Others are tested when a calculator puts the chance of a family fault at 10 percent or more.",
    summary: "NICE NG101 (1.3.5, 2017) tells clinicians to offer genetic testing for BRCA1 and BRCA2 mutations to women under 50 years with triple-negative breast cancer, including those with no family history of breast or ovarian cancer, and points to the National Genomic Test Directory for the criteria that govern testing for NICE-recommended PARP inhibitors (R444.1). NICE CG164 sets the general framework: in secondary care and specialist clinics a carrier probability calculator with acceptable performance, such as CanRisk (BOADICEA) or the Manchester scoring system, is used; genetic testing is offered to a person with breast or ovarian cancer whose combined BRCA1 and BRCA2 carrier probability is 10 percent or more, to an affected relative at the same threshold, or to an unaffected person at 10 percent or more when no affected relative is available; fast-track testing within four weeks of diagnosis was to be offered only in a trial; every person offered testing should have a detailed consultation with a clinical geneticist or genetics counsellor; and clinicians should seek genetics advice for families containing triple-negative breast cancer under 40, Jewish ancestry, sarcoma under 45, glioma or childhood adrenal cortical carcinoma, complicated patterns of cancers at a young age or a very strong paternal history. A 2024 UK study of 1,061 women with breast cancer across three cohorts found pathogenic variants in 3.4 percent (BRCA1 9, BRCA2 18, PALB2 9); the current mainstream criteria, women diagnosed under 40, all triple-negative disease under 60, or a Manchester score of 15 or more, identified 58 percent of variants by testing 190 women (detection rate 8.4 percent, specificity 83.5 percent), a Manchester threshold of 12 raised sensitivity to 66.7 percent, no variant was found in 158 women with grade 1 cancers, and the authors argue for lowering the threshold to detect more carriers (Evans 2024). The yield in triple-negative disease justifies the special rule: 11.2 percent BRCA1/2 and 14.6 percent any predisposition gene among 1,824 unselected patients (Couch 2015); 15.4 percent BRCA1/2 in a prospective registry, 27.6 percent at 50 or under, 11.4 percent at 51 to 60 and 4.9 percent at 61 or over, with NCCN's rule of testing all triple-negative disease at 60 or under catching every carrier (Sharma 2014). A positive result opens adjuvant olaparib for high-risk early disease (NICE TA886), informs surgery, and starts cascade testing of relatives; Cancer Research UK notes that testing usually starts with the affected family member most likely to carry the change.",
    cancers: ["tnbc", "brca-associated-tnbc", "tnbc-early", "breast-cancer"], terms: ["germline-vs-somatic", "risk-reducing-surgery-brca-carriers"], technologies: ["germline-testing"], targets: ["brca"],
    links: [SRC.ng101, SRC.cg164, SRC.evans2024, SRC.couch2015, SRC.sharma2014, SRC.crukFamily, SRC.ta886] }),

  tm({ id: "ki-67-in-tnbc", name: "Ki-67 in triple-negative breast cancer", category: "Biomarkers", wikipedia: W("Ki-67_(protein)"),
    aka: ["Ki67 in TNBC", "Proliferation index in triple-negative breast cancer", "MIB-1 in triple-negative breast cancer"],
    tldr: "Ki-67 is a stain that marks dividing cells. Triple-negative cancers almost all score high, typically around 60 percent, so the marker separates them from slower hormone-driven cancers but rarely changes treatment within the triple-negative group; the international working group limits its clinical use to hormone receptor-positive disease.",
    summary: "Ki-67 immunohistochemistry is a proliferation marker whose clinical use has been limited by questionable analytical validity. The International Ki67 in Breast Cancer Working Group (2019 meeting, published 2021) concluded that preanalytical handling is critical, recommended a standardised visual scoring method and quality assurance, accepted clinical validity as a prognostic marker, but found clinical utility only for prognosis in anatomically favourable ER-positive, HER2-negative T1 to T2, N0 to N1 disease, where 5 percent or less or 30 percent or more can be used to identify who does not need adjuvant chemotherapy (Nielsen 2021). Triple-negative tumours sit far above those thresholds: the Swedish population cohort of 5,655 tumours treated as triple-negative had a median Ki-67 of 63 percent in ER-zero and 60 percent in ER-low tumours (Acs 2024). Within triple-negative disease Ki-67 still carries information: in 105 Korean patients treated with neoadjuvant docetaxel and doxorubicin, tumours with Ki-67 of 10 percent or more had a pathological complete response rate of 18.2 percent against 0 percent below 10 percent, yet high Ki-67 was independently associated with worse relapse-free survival (hazard ratio 7.82) and overall survival, and the low-Ki-67 group showed a constant rather than early-peaking hazard of relapse (Keam 2011), the pattern of the luminal androgen receptor and special-type tumours. Grade 3 and high Ki-67 also enter the AJCC prognostic stage through grade. The ki-67-index readout and the ki67-mib1 assay records carry the scoring detail.",
    cancers: ["tnbc", "tnbc-luminal-androgen-receptor", "breast-hr-positive"], terms: ["tumour-grade", "pcr", "ajcc-prognostic-stage-breast"], technologies: ["histopathology-ihc"],
    links: [SRC.nielsen2021, SRC.acs2024, SRC.keam2011] }),

  tm({ id: "basal-like", name: "Basal-like breast cancer", category: "Cancer biology", wikipedia: W("Basal-like_carcinoma"),
    aka: ["Basal-like subtype", "Basal breast cancer", "Basal-like intrinsic subtype", "PAM50 basal-like", "Basal-like carcinoma"],
    tldr: "Basal-like is a breast cancer subtype defined by the genes its cells switch on, which resemble the basal cells lining the milk ducts. About four in five triple-negative cancers are basal-like and most basal-like cancers are triple-negative, but the two labels are not the same thing, and the overlap is where BRCA1-related cancers sit.",
    summary: "Perou and colleagues profiled 65 surgical specimens from 42 patients on cDNA microarrays of 8,102 genes and found the tumours could be classified into subtypes distinguished by pervasive differences in gene expression, the origin of the intrinsic subtypes luminal A, luminal B, HER2-enriched, basal-like and normal-like (Perou 2000). The Cancer Genome Atlas integrated copy number, methylation, exome, mRNA, microRNA and protein data across primary breast cancers, confirmed four main classes, found TP53, PIK3CA and GATA3 the only genes mutated in more than 10 percent overall, and showed basal-like tumours share many molecular features with high-grade serous ovarian cancer, implying a related aetiology and similar therapeutic opportunities (TCGA 2012). Triple-negative and basal-like overlap but are not identical: of 412 triple-negative tumours 21.4 percent were non-basal-like, and of 473 basal-like tumours 31.5 percent were not triple-negative; triple-negative tumours classified as luminal or HER2-enriched had expression profiles indistinguishable from their non-triple-negative counterparts, most HER2-enriched triple-negative tumours lacked HER2 amplification, and the authors suggest triple-negative trials stratify by basal-like versus non-basal-like expression (Prat 2013). In the population-based Carolina Breast Cancer Study, using immunohistochemical surrogates (ER, PR and HER2 negative with cytokeratin 5/6 or HER1 positive), basal-like tumours were found in 39 percent of premenopausal African American women against 14 percent of postmenopausal African American and 16 percent of non-African American women; they had more TP53 mutations (44 against 15 percent), higher mitotic index and grade, and among the shortest breast cancer-specific survival (Carey 2006). Basal-like cancers are the typical cancer of BRCA1 carriers, and adenoid cystic carcinoma is a special type of basal-like tumour with an excellent outlook (Ghabach 2010), a reminder that the label describes lineage, not behaviour. Within triple-negative disease Lehmann's basal-like 1 and 2 subtypes subdivide the group.",
    cancers: ["tnbc", "tnbc-basal-like-1", "tnbc-basal-like-2", "brca-associated-tnbc", "adenoid-cystic-carcinoma-breast", "high-grade-serous-ovarian-cancer"], terms: ["claudin-low"], targets: ["tp53", "brca"],
    links: [SRC.perou2000, SRC.tcga2012, SRC.prat2013, SRC.carey2006, SRC.ghabach2010] }),

  tm({ id: "claudin-low", name: "Claudin-low breast cancer", category: "Cancer biology", wikipedia: W("Claudin"),
    aka: ["Claudin-low subtype", "Claudin-low phenotype", "Claudin-low triple-negative breast cancer"],
    tldr: "Claudin-low breast cancers have lost the claudin proteins that hold epithelial cells together and have taken on the features of migrating, stem-like cells. Most are triple-negative and respond to chemotherapy less well than basal-like cancers. Newer work treats claudin-low as a pattern that can overlay any subtype rather than a subtype of its own.",
    summary: "Prat and colleagues characterised the claudin-low subtype across an updated human tumour database, cell lines and mouse models: low to absent expression of luminal differentiation markers, high enrichment for epithelial-to-mesenchymal transition markers, immune response genes and cancer stem cell-like features; clinically most are poor-prognosis ER-, PR- and HER2-negative invasive ductal carcinomas with a high frequency of metaplastic and medullary differentiation, with a response rate to standard preoperative chemotherapy intermediate between basal-like and luminal tumours; the subtype most closely resembles the mammary epithelial stem cell in a differentiation hierarchy (Prat 2010). Fougner and colleagues re-examined claudin-low tumours with genomic, transcriptomic and clinical data and concluded that claudin-low is not a subtype analogous to the intrinsic subtypes but a complex additional phenotype that may permeate tumours of various intrinsic subtypes, distinguished by low genomic instability, low mutational burden, low proliferation and high immune and stromal infiltration while otherwise reflecting the intrinsic subtype; they also found weaknesses in the established classifier (Fougner 2020). In Lehmann's triple-negative classification the mesenchymal and mesenchymal stem-like subtypes carry the same epithelial-to-mesenchymal transition biology, and the parent record names mesenchymal and claudin-low disease as the biology that resists chemotherapy, ADC payloads and immunotherapy alike.",
    cancers: ["tnbc", "tnbc-mesenchymal", "tnbc-mesenchymal-stem-like", "metaplastic-breast-carcinoma"], terms: ["basal-like"], pathways: ["emt"],
    links: [SRC.prat2010, SRC.fougner2020, SRC.lehmann2011] }),

  tm({ id: "androgen-receptor-positive-tnbc", name: "Androgen receptor-positive triple-negative breast cancer", category: "Biomarkers", wikipedia: W("Androgen_receptor"),
    aka: ["AR-positive TNBC", "AR-positive breast cancer", "Androgen receptor expression in breast cancer", "AR immunohistochemistry 10 percent"],
    tldr: "Some triple-negative breast cancers carry the androgen receptor, the protein that prostate cancer runs on. About one in eight ER-negative cancers stain positive, and in trials the prostate drugs bicalutamide and enzalutamide held the disease for a minority of patients; neither is approved for breast cancer, so this remains a trial question.",
    summary: "Androgen receptor is scored by nuclear immunohistochemistry; the trials used more than 10 percent of nuclei as positive, and the enzalutamide trial also enrolled any staining above 0 percent. Of 424 patients with ER- and PR-negative advanced breast cancer screened centrally, 12 percent were AR-positive by the 10 percent rule; bicalutamide 150 mg daily gave a six-month clinical benefit rate of 19 percent (complete or partial response or stable disease over six months) and median progression-free survival of 12 weeks, with no grade 4 or 5 treatment-related events (Gucalp 2013). Enzalutamide 160 mg daily in 118 patients with locally advanced or metastatic AR-positive triple-negative disease gave a 16-week clinical benefit rate of 25 percent overall and 33 percent in the 78 evaluable patients with 10 percent or more nuclear staining, median progression-free survival of 2.9 and 3.3 months and median overall survival of 12.7 and 17.6 months; fatigue was the only treatment-related grade 3 or higher event above 2 percent (Traina 2018). AR expression defines the luminal androgen receptor subtype of Lehmann and Burstein and the molecular apocrine group, whose cells were uniquely sensitive to bicalutamide in the laboratory (Lehmann 2011); LAR tumours are less proliferative and less chemosensitive (29 percent pathological complete response against 41 percent for basal-like 1, Lehmann 2016). Neither antiandrogen is approved for breast cancer; the subtype page carries the biology and the trials with PI3K-pathway inhibitors.",
    cancers: ["tnbc", "tnbc-luminal-androgen-receptor", "apocrine-carcinoma-breast"], targets: ["androgen-receptor"], drugs: ["bicalutamide", "enzalutamide"], terms: ["pcr"],
    links: [SRC.gucalp2013, SRC.traina2018, SRC.lehmann2011, SRC.lehmann2016] }),

  tm({ id: "ajcc-prognostic-stage-breast", name: "AJCC 8th edition prognostic stage for breast cancer", category: "Clinic basics", wikipedia: W("Breast_cancer_classification"),
    aka: ["Prognostic stage group", "Clinical prognostic stage", "Pathological prognostic stage", "Anatomic stage versus prognostic stage", "AJCC 8th edition breast"],
    tldr: "Since 2018 the American staging system gives breast cancer two stages: the anatomic stage from tumour size, nodes and spread, and a prognostic stage that also counts grade and the three receptors. Because triple-negative cancers are usually grade 3 and receptor negative, their prognostic stage is often a step higher than their anatomic stage; UK pages and NICE quote the anatomic TNM stage.",
    summary: "The eighth edition of the American Joint Committee on Cancer TNM classification for breast cancer, prepared by a multidisciplinary panel, kept the anatomic TNM stage so the system stays usable worldwide, but recognised the prognostic influence of grade, oestrogen and progesterone receptor expression and HER2 amplification and mandated their inclusion, and acknowledged gene expression panels: tumour biomarkers and a low Oncotype DX recurrence score can alter the stage, giving a flexible platform that will be updated online (Giuliano 2017). Validation in 3,327 patients with stage I to IIIC disease treated with surgery first at MD Anderson (2007 to 2013) found the prognostic stage moved 29.5 percent of patients up and 28.1 percent down relative to the anatomic stage, and stratified disease-specific survival better (C index 0.8357 against 0.737); in 54,727 patients in the California Cancer Registry (2005 to 2009) it upstaged 31.0 percent and downstaged 20.6 percent and again performed better (C index 0.8426), supporting its use (Weiss 2018). Patients treated with neoadjuvant systemic therapy were excluded from that validation, which matters for triple-negative disease, where most stage II and III patients now have chemotherapy first and the response at surgery (pathological complete response or residual cancer burden) is the stronger prognostic marker. Cancer Research UK describes the TNM 8th edition and the number stages in plain words and notes that the TNM system is the commonest way to stage breast cancer in the UK, with staging confirmed after surgery; UK clinicians do not usually quote the prognostic stage group.",
    cancers: ["tnbc", "breast-cancer", "breast-hr-positive", "breast-her2-positive"], terms: ["tnm-staging", "tumour-grade", "pcr", "rcb"],
    links: [SRC.giuliano2017, SRC.weiss2018, SRC.crukTnm, SRC.crukStages] }),

  tm({ id: "interval-breast-cancer", name: "Interval breast cancer (a cancer found between screening rounds)", category: "Epidemiology & prevention", wikipedia: W("Breast_cancer_screening"),
    aka: ["Interval cancer", "Screen-detected versus interval cancer", "Cancer between mammograms", "NHS Breast Screening Programme interval"],
    tldr: "An interval breast cancer is one diagnosed after a normal screening mammogram and before the next invitation. Fast-growing cancers, triple-negative disease among them, make up a larger share of interval than of screen-detected cancers, which is why a new breast change should always be checked rather than left until the next screen.",
    summary: "The NHS Breast Screening Programme invites everyone registered as female with a GP from age 50 (first invitation between 50 and 53) every three years until the 71st birthday, and women 71 or over can request screening; anyone worried about symptoms should see a GP even if recently screened rather than wait for the next appointment (NHS). An interval cancer emerges after a negative screen. In population programmes, most based on two-yearly screening, reported interval cancer rates ranged from 7.0 to 49.3 per 10,000 screens, usually 8.4 to 21.1 per 10,000 across the two-year interval with the larger share in the second year; on retrospective review most interval cancers were true interval or occult cancers not visible on the index mammogram and about 20 to 25 percent were classified as missed; interval cancers have worse prognostic characteristics, biomarker profiles and survival than screen-detected cancers but resemble cancers in unscreened women (Houssami 2017). Triple-negative disease is over-represented: in 15,204 women at US NCCN centres only 29 percent of triple-negative cancers presented through an abnormal screening mammogram against 48 percent of hormone receptor-positive, HER2-negative cancers (Lin 2012), and triple-negative tumours are diagnosed younger, before the screening age in many cases (Bauer 2007; Scott 2019). Women at high familial risk are screened differently: NICE CG164 offers annual MRI from 30 to 49 and annual mammography from 40 to 69 to known BRCA1 or BRCA2 carriers, and in the UK MARIBS study MRI detected 77 percent of cancers against 40 percent for mammography, 92 against 23 percent in BRCA1 carriers, with two interval cases among 35 cancers in 1,881 screens (Leach 2005).",
    cancers: ["tnbc", "breast-cancer", "brca-associated-tnbc"], technologies: ["mammography", "mri"], terms: ["germline-brca-testing-criteria-tnbc"],
    links: [SRC.nhsScreeningWho, SRC.houssami2017, SRC.lin2012, SRC.cg164, SRC.leach2005] }),

  tm({ id: "risk-reducing-surgery-brca-carriers", name: "Risk-reducing surgery for BRCA carriers (bilateral and contralateral mastectomy, salpingo-oophorectomy)", category: "Procedures", wikipedia: W("Prophylactic_mastectomy"),
    aka: ["Bilateral risk-reducing mastectomy", "Prophylactic mastectomy", "Contralateral risk-reducing mastectomy", "Risk-reducing salpingo-oophorectomy and breast cancer", "Preventive mastectomy"],
    tldr: "Women who carry a BRCA1 or BRCA2 fault can choose to have both breasts removed before any cancer appears, which cuts breast cancer risk by about nine tenths, or to remove the other breast after a first cancer. Removing the ovaries protects against ovarian cancer but, in the largest prospective study, did not lower breast cancer risk in BRCA1 carriers.",
    summary: "In the PROSE study, breast cancer was diagnosed in 2 of 105 BRCA1/2 carriers (1.9 percent) who had bilateral prophylactic mastectomy against 184 of 378 matched carriers (48.7 percent) who did not, over a mean 6.4 years, a risk reduction of about 90 percent with intact ovaries and 95 percent with prior or concurrent oophorectomy (Rebbeck 2004). A meta-analysis of 15 studies found bilateral prophylactic mastectomy reduced breast cancer risk in carriers (relative risk 0.114), contralateral prophylactic mastectomy reduced contralateral breast cancer (0.072) and all-cause mortality in carriers with breast cancer (hazard ratio 0.512), and prophylactic salpingo-oophorectomy reduced breast cancer risk (0.552) and all-cause mortality with and without breast cancer; bilateral mastectomy was not significantly associated with lower all-cause mortality (Li 2016). The oophorectomy effect on breast cancer is disputed: in a prospective cohort of 3,722 carriers with no cancer history, oophorectomy was not associated with breast cancer risk in BRCA1 carriers (hazard ratio 0.96) and protected BRCA2 carriers only before 50 (0.18) (Kotsopoulos 2017). NICE CG164 restricts bilateral risk-reducing mastectomy to a small proportion of women from high-risk families managed by a multidisciplinary team, with genetic counselling in a specialist clinic, verification of the family history where no mutation is identified, pre-operative counselling on psychosocial and sexual consequences and the possibility of finding a cancer in the specimen, discussion of immediate and delayed reconstruction with an oncoplastic team, access to support groups, no surveillance afterwards and no chemoprevention after the operation; the same restrictions apply to risk-reducing oophorectomy, and the combined pill should not be prescribed purely for ovarian risk reduction in a BRCA1 carrier considering oophorectomy before 40. Cancer Research UK explains that the surgeon cannot remove every breast cell, so the risk falls but does not vanish, and that reconstruction can be done at the same time or later. For carriers who already have triple-negative disease, the POSH authors advise weighing the prognosis of the first cancer before further surgery (Copson 2018).",
    cancers: ["tnbc", "brca-associated-tnbc", "breast-cancer", "ovarian"], terms: ["mastectomy", "germline-brca-testing-criteria-tnbc", "chemoprevention-and-er-negative-breast-cancer"], technologies: ["germline-testing"],
    links: [SRC.rebbeck2004, SRC.li2016, SRC.kotsopoulos2017, SRC.cg164, SRC.crukFamily, SRC.copson2018] }),

  tm({ id: "chemoprevention-and-er-negative-breast-cancer", name: "Chemoprevention (tamoxifen, anastrozole, raloxifene) and ER-negative breast cancer", category: "Epidemiology & prevention", wikipedia: W("Tamoxifen"),
    aka: ["Breast cancer chemoprevention", "Tamoxifen for prevention", "Anastrozole for prevention", "IBIS-I", "IBIS-II", "NSABP P-1", "Preventive tamoxifen and BRCA1"],
    tldr: "Tamoxifen and anastrozole taken for five years cut the number of new breast cancers in women at raised risk by a third to a half, and NICE offers them to women at high or moderate risk. But the cancers they prevent are oestrogen-driven ones; in the trials they made no difference to oestrogen receptor-negative cancers, the kind BRCA1 carriers mostly get.",
    summary: "NICE CG164 offers tamoxifen for five years to premenopausal women at high risk of breast cancer (unless they have a history or increased risk of thromboembolic disease or endometrial cancer), anastrozole for five years to postmenopausal women at high risk (unless they have severe osteoporosis), tamoxifen or off-label raloxifene as alternatives, considers the same drugs at moderate risk, and does not offer chemoprevention after bilateral risk-reducing mastectomy. The trials behind those offers were run in women defined by family history or age-related risk, and their effect was confined to ER-positive disease. IBIS-I randomised 7,154 women aged 35 to 70 at increased risk to tamoxifen 20 mg or placebo for five years; after a median 16 years, breast cancer occurred in 7.0 against 9.8 percent (hazard ratio 0.71), with the reduction similar in years 0 to 10 and after 10 years, the greatest effect on invasive ER-positive cancer (0.66) and ductal carcinoma in situ (0.65), and no effect on invasive ER-negative cancer (1.05) (Cuzick 2015). NSABP P-1 randomised 13,388 women to tamoxifen or placebo; tamoxifen reduced invasive breast cancer by 49 percent and ER-positive tumours by 69 percent, with no difference in ER-negative tumours, at the cost of more endometrial cancer (risk ratio 2.53), stroke, pulmonary embolism and deep-vein thrombosis, mainly in women 50 or older (Fisher 1998). IBIS-II randomised 3,864 postmenopausal women at increased risk to anastrozole 1 mg or placebo for five years; after a median 131 months breast cancer fell by 49 percent (85 against 165 cases), invasive ER-positive cancer by 54 percent and ductal carcinoma in situ by 59 percent, with no excess of fractures or cardiovascular disease and no difference in deaths (Cuzick 2020). Cancer Research UK notes that the evidence is unclear for women with gene changes. For carriers who have already had a breast cancer, pooled observational cohorts found tamoxifen associated with a lower risk of contralateral breast cancer in BRCA1 (hazard ratio 0.38) and BRCA2 carriers (0.33), not differing by the ER status of the first cancer, though the prospective-only estimates were weaker (0.58 and 0.48) (Phillips 2013). No drug is proven to prevent ER-negative or triple-negative breast cancer; surveillance, risk-reducing surgery and breastfeeding (Palmer 2014) are what the evidence supports for BRCA1 carriers.",
    cancers: ["tnbc", "brca-associated-tnbc", "breast-hr-positive", "breast-cancer"], drugs: ["tamoxifen", "anastrozole", "raloxifene"], technologies: ["chemoprevention", "endocrine-therapy"], targets: ["estrogen-receptor"], terms: ["risk-reducing-surgery-brca-carriers"],
    links: [SRC.cg164, SRC.cuzick2015, SRC.fisher1998, SRC.cuzick2020, SRC.phillips2013, SRC.crukFamily, SRC.palmer2014] }),

  // ---- Terms the evidence file of this deep dive links to ----
  tm({ id: "founder-mutation", name: "Founder mutation (BRCA1 185delAG and 5382insC, BRCA2 6174delT)", category: "Genomics & genetics", wikipedia: W("Founder_effect"),
    aka: ["Founder variant", "Ashkenazi BRCA founder mutations", "BRCA1 185delAG", "BRCA1 5382insC", "BRCA2 6174delT", "Population-specific BRCA mutation"],
    tldr: "A founder mutation is a single inherited gene fault that many people in one population share because they descend from the same ancestor who carried it. The best known are three BRCA faults carried by about one in forty Ashkenazi Jews, which is why Jewish ancestry is one of the family history flags in UK genetics referral rules.",
    summary: "In a population study of about 3,000 Ashkenazi Jewish individuals unselected for breast cancer, the BRCA1 185delAG mutation had a carrier frequency of 1.09 percent and 5382insC 0.13 percent, and in 3,085 individuals the BRCA2 6174delT mutation 1.52 percent, confirming 185delAG and 6174delT as the two most frequent alleles predisposing to hereditary breast cancer among the Ashkenazim and suggesting lower penetrance for 6174delT (Roa 1996). Among 5,318 Jewish volunteers in Washington, 120 carriers of one of the three mutations were identified; by age 70 the estimated risk of breast cancer among carriers was 56 percent (95 percent confidence interval 40 to 73), of ovarian cancer 16 percent and of prostate cancer 16 percent, with no difference between BRCA1 and BRCA2 carriers and risks well below the 85 percent estimated from high-risk families (Struewing 1997). Because the combined frequency exceeds 2 percent, testing for the three variants is informative in this population without a family history, and NICE CG164 lists Jewish ancestry among the features for which clinicians should seek advice from a specialist genetics service and asks clinics to record ethnic background when assessing carrier probability; Cancer Research UK's family history page names a Jewish background as a reason the clinic may consider testing more likely to be useful. BRCA1 founder mutations matter for triple-negative disease because BRCA1-associated cancers are mostly basal-like and triple-negative (Atchley 2008). Other populations have their own founder alleles; the history on the parent page records the Polish BRCA1 variants beside the Ashkenazi ones.",
    cancers: ["tnbc", "brca-associated-tnbc", "breast-cancer", "ovarian"], terms: ["germline-brca-testing-criteria-tnbc", "germline-vs-somatic"], targets: ["brca"], technologies: ["germline-testing"],
    links: [SRC.roa1996, SRC.struewing1997, SRC.cg164, SRC.crukFamily, SRC.atchley2008] }),

  tm({ id: "idfs", name: "Invasive disease-free survival (iDFS)", category: "Endpoints", wikipedia: W("Survival_rate"),
    aka: ["iDFS", "Invasive disease-free survival", "Invasive breast cancer-free survival (IBCFS)", "STEEP end points", "Disease-free survival in adjuvant breast cancer trials"],
    tldr: "Invasive disease-free survival is the yardstick of most trials that treat early breast cancer after surgery. A patient counts as an event if the cancer comes back anywhere as invasive disease, a new invasive cancer appears in either breast or elsewhere, or she dies of any cause; it deliberately ignores non-invasive recurrences. OlympiA used it to show that a year of olaparib helped BRCA carriers.",
    summary: "The Standardized Definitions for Efficacy End Points (STEEP) system was proposed in 2007 by a panel of medical oncologists, biostatisticians and correlative scientists so that a given end point term in an adjuvant breast cancer trial always encompasses the same set of events and each event is defined the same way across end points and studies, permitting cross-trial comparison and meta-analysis (Hudis 2007). Invasive disease-free survival is the STEEP end point that counts invasive recurrence in the ipsilateral breast, chest wall or regional nodes, distant recurrence, a new invasive cancer in the contralateral breast, a second non-breast primary cancer and death from any cause, and excludes in situ recurrences. STEEP version 2.0 (2021) found that of 11 phase III breast cancer trials with primary efficacy end points only three followed STEEP criteria, showed by simulation that including second non-breast primary cancers can reduce power and mask differences in recurrence when recurrence rates are low, and recommended an additional end point, invasive breast cancer-free survival, which drops second non-breast primaries, for trials of agents with known toxicity and a small second-cancer risk (Tolaney 2021). In OlympiA, 1,836 patients with germline BRCA1 or BRCA2 pathogenic variants and high-risk HER2-negative early breast cancer were randomised to a year of olaparib or placebo after local treatment and chemotherapy; three-year invasive disease-free survival was 85.9 against 77.1 percent (hazard ratio 0.58) and distant disease-free survival 87.5 against 80.4 percent (0.57), with fewer deaths on olaparib (59 against 86) that did not reach the interim boundary (Tutt 2021); the parent page's history carries the later overall survival update. Event-free survival, the KEYNOTE-522 end point, differs in starting before surgery so that progression precluding surgery counts as an event.",
    cancers: ["tnbc", "tnbc-early", "brca-associated-tnbc", "breast-cancer"], terms: ["pcr", "rcb"], trials: ["olympia", "keynote-522"], drugs: ["olaparib"],
    links: [SRC.hudis2007, SRC.tolaney2021, SRC.tutt2021] }),

  tm({ id: "luminal-androgen-receptor", name: "Luminal androgen receptor (LAR) subtype", category: "Cancer biology", wikipedia: W("Androgen_receptor"),
    aka: ["LAR", "LAR subtype of TNBC", "TNBCtype LAR", "Luminal AR subtype"],
    tldr: "Luminal androgen receptor is one of the four molecular subtypes of triple-negative breast cancer. Its cells look and behave like hormone-driven luminal cells but run on the androgen receptor instead of oestrogen, which makes them slower growing, less responsive to chemotherapy and the target of trials with prostate cancer drugs.",
    summary: "The LAR subtype was one of six triple-negative expression clusters identified in 587 tumours, characterised by androgen receptor signalling, including patients with decreased relapse-free survival, and with cell lines uniquely sensitive to bicalutamide (Lehmann 2011). It survived the 2016 refinement to four tumour-specific subtypes (BL1, BL2, M and LAR) and had a pathological complete response rate of 29 percent across five neoadjuvant datasets against 41 percent for BL1 and 18 percent for BL2 (Lehmann 2016), and 10 percent in the MD Anderson series (Masuda 2013). Burstein's independent classification also finds an LAR group, with the androgen receptor and MUC1 as candidate targets and a distinct DNA copy number profile (Burstein 2015). The subtype page tnbc-luminal-androgen-receptor carries the overlap with molecular apocrine and histological apocrine carcinoma and the bicalutamide and enzalutamide trials; the androgen receptor-positive term carries the immunohistochemistry thresholds.",
    cancers: ["tnbc", "tnbc-luminal-androgen-receptor", "apocrine-carcinoma-breast"], terms: ["androgen-receptor-positive-tnbc", "basal-like", "pcr"], targets: ["androgen-receptor"],
    links: [SRC.lehmann2011, SRC.lehmann2016, SRC.masuda2013, SRC.burstein2015] }),

  tm({ id: "pd-l1-assay-discordance", name: "PD-L1 assay discordance (SP142, SP263 and 22C3 in breast cancer)", category: "Biomarkers", wikipedia: W("PD-L1"),
    aka: ["PD-L1 assay comparison", "SP142 versus 22C3", "PD-L1 antibody clones", "PD-L1 test harmonisation", "Non-interchangeable PD-L1 assays"],
    tldr: "Three commercial PD-L1 stains give different answers on the same breast tumour: the SP142 assay used with atezolizumab called fewer than half of tumours positive while the 22C3 and SP263 assays called about three quarters. Because the pembrolizumab licence rests on 22C3 combined positive score 10, which test a laboratory runs, and how it scores it, decides who is offered immunotherapy.",
    summary: "In a central re-analysis of 614 IMpassion130 tumours (68.1 percent of the trial population), PD-L1 on immune cells at 1 percent or more was present in 46.4 percent by VENTANA SP142, 74.9 percent by SP263 and 73.1 percent by Dako 22C3, and 80.9 percent had a 22C3 combined positive score of 1 or more; analytical concordance of SP263 and 22C3 with SP142 was 69.2 and 68.7 percent; almost all SP142-positive cases were positive on the other assays, but 29.6 percent of SP263-positive and 29.0 percent of 22C3-positive cases were SP142-negative; the atezolizumab benefit in SP263- and 22C3-positive patients (progression-free survival hazard ratios 0.64 to 0.68, overall survival 0.75 to 0.79) was driven by the double-positive cases, and single-positive cases showed overall survival hazard ratios of 0.87 to 0.95 (Rugo 2021, the paper record on this site). The assays also answer different questions: SP142 in IMpassion130 scored PD-L1 on tumour-infiltrating immune cells as a percentage of tumour area at a 1 percent cut-off (Schmid 2018), whereas KEYNOTE-355 used the 22C3 combined positive score, which counts staining tumour cells, lymphocytes and macrophages against all viable tumour cells, with the benefit confined to CPS 10 or more (Cortes 2020; Cortes 2022). Only the 22C3 CPS 10 threshold has an approved and NICE-recommended drug attached in triple-negative disease (TA801); the parent page records that the atezolizumab US indication was withdrawn and lists assay harmonisation among its open problems. The biomarker readouts pd-l1-cps and pd-l1-ic-score carry the label wording for each score.",
    cancers: ["tnbc", "tnbc-metastatic"], terms: ["pd-l1-cps-10-tnbc", "cps"], targets: ["pdl1"], drugs: ["pembrolizumab", "atezolizumab"], trials: ["impassion130", "keynote-355"], keyPapers: ["paper-rugo-pd-l1-assay-comparison-impassion130-jnci-2021"],
    links: [SRC.rugo2021, SRC.schmid2018, SRC.cortes2020, SRC.ta801] }),

  tm({ id: "exceptional-responder", name: "Exceptional responder", category: "Trials", wikipedia: W("Clinical_endpoint"),
    aka: ["Exceptional response", "Exceptional Responders Initiative", "Outlier responder", "Super-responder", "Long-term responder"],
    tldr: "An exceptional responder is a patient whose cancer shrinks or stays controlled far longer than expected on a treatment that helps few people. The US National Cancer Institute defined the term for a study that sequenced such patients' tumours to learn why, and found a plausible molecular reason in about a quarter of them.",
    summary: "The National Cancer Institute's Exceptional Responders Initiative defined an exceptional response as a partial or complete response to a systemic treatment whose population response rate is under 10 percent, or an unusually long response, for example lasting more than three times the published median. Of 520 cases proposed by clinicians, 476 were accepted for review, 222 met the definition, clinical data were obtained for 168, tumour tissue for 130, and 109 were successfully analysed by whole exome sequencing and, where possible, targeted deep sequencing, RNA sequencing, methylation arrays and immunohistochemistry; six patients had potentially actionable germline mutations, and the authors concluded that retrospective identification and sequencing of archived pretreatment tissue is feasible (Conley 2021). Integrative analysis of 111 exceptional responders uncovered plausible mechanisms in nearly a quarter, assigned to four categories, DNA damage response, intracellular signalling, immune engagement and genetic alterations characteristic of favourable prognosis, with many tumours in more than one, revealing synthetic lethal relationships and rare lesions that favour therapeutic success (Wheeler 2021). In triple-negative breast cancer the label is applied to the minority of patients with metastatic disease whose responses to immunotherapy or ADCs last for years, and the roadmap on this site tracks the studies that try to explain them; the term is a definition of an outcome, not a biomarker, and a single case cannot establish that a drug works.",
    cancers: ["tnbc", "tnbc-metastatic"], terms: ["pd-l1-cps-10-tnbc", "hrd-in-breast-cancer"],
    links: [SRC.conley2021, SRC.wheeler2021] }),

  tm({ id: "health-disparities", name: "Health disparities in cancer outcomes (ethnicity, deprivation and access)", category: "Epidemiology & prevention", wikipedia: W("Health_equity"),
    aka: ["Cancer outcome disparities", "Racial disparities in breast cancer", "Ethnic inequalities in cancer", "Deprivation and cancer survival", "Disparities versus biology"],
    tldr: "Health disparities are differences in who gets a cancer and who survives it that track ethnicity, income and access to care rather than chance. Triple-negative breast cancer is the textbook case: Black women get it about twice as often, present later and die of it more often, and the question of how much is biology and how much is unequal care is still being worked out on both sides of the Atlantic.",
    summary: "United States: the SEER 21 rate of hormone receptor-negative, HER2-negative breast cancer is 25.7 per 100,000 in non-Hispanic Black women against 13.0 in non-Hispanic White women (2019 to 2023), and non-Hispanic Black women had 2.27 times the odds of a triple-negative diagnosis in 1,151,724 cases from 2010 to 2014, with stage III and IV disease also more likely (Scott 2019); in the California registry non-Hispanic Black women with late-stage triple-negative disease had a five-year relative survival of 14 percent, the poorest of any group (Bauer 2007); basal-like tumours were found in 39 percent of premenopausal African American women against 16 percent of others (Carey 2006); and even after controlling for treatment delays, stage and socioeconomic factors, African American women with triple-negative disease remain nearly twice as likely to die of it (Howard and Olopade 2021). Whether this reflects a molecularly distinct disease or a higher incidence of aggressive biology driven by disparities has evidence on both sides (Dietze 2015); in 687 young Black women, triple-negative disease (hazard ratio 1.81) and node involvement shortened disease-free survival, full-time employment lengthened it (0.44), and a higher percentage of West African genetic ancestry shortened it within hormone receptor-positive disease (1.45), pointing to ancestry beyond self-reported race and to social determinants together (Reid 2024). United Kingdom: in the POSH cohort of women diagnosed at 40 or under, triple-negative tumours were more frequent in Black (26.1 percent) than White (18.6 percent) patients, chemotherapy use was equally high, yet five-year overall survival was 71.1 against 82.4 percent and Black ethnicity independently predicted distant relapse in ER-positive disease, despite equal access to NHS care (Copson 2014); in 116,500 women in England (2013 to 2018) all ethnic minority groups had greater adjusted odds of high-stage, high-grade or ER-negative tumours, most marked in Black African and Black Caribbean women and larger in older women (Gathani 2021). Deprivation acts alongside ethnicity: five-year survival for breast cancer in England is 82.6 percent in the most deprived group against 89.6 percent in the least (2018 to 2022), and breast cancer mortality rates in UK women are 12 percent higher in the most deprived quintile, with about 650 deaths a year linked to deprivation (Cancer Research UK). Trial enrolment does not reflect the burden, which the parent record lists among its open problems.",
    cancers: ["tnbc", "breast-cancer", "tnbc-early"], terms: ["basal-like", "interval-breast-cancer"],
    links: [SRC.seerSubtypes, SRC.scott2019, SRC.bauer2007, SRC.carey2006, SRC.howardOlopade, SRC.dietze2015, SRC.reid2024, SRC.copson2014, SRC.gathani2021, SRC.crukSurv, SRC.crukMort] }),
];

